helper:
globalThis.cards=load("cards");globalThis.knowledge=load("knowledge");globalThis.handling=load("handling");globalThis.ctr=load("counters");
globalThis.unit=function(block,n){return block+"-P"+String(n).padStart(3,"0");}
globalThis.add=function(ch,topic,task,front,parts,extra={}){
 const id="RB-CN"+String(ch).padStart(2,"0")+"-"+String(++ctr[ch]).padStart(4,"0");
 const ks=[]; const answers=[];const rubrics=[];const all=new Set(extra.source_units||[]);
 parts.forEach((p,i)=>{
  const a="A"+(i+1),r="R"+(i+1),kid="KP-CN"+String(ch).padStart(2,"0")+"-"+String(++ctr["k"+ch]).padStart(4,"0");
  ks.push(kid); answers.push({anchor:a,text:p[1]});rubrics.push({anchor:r,text:p[2]});
  const units=p[3];units.forEach(u=>all.add(u));
  knowledge.push({knowledge_id:kid,knowledge:p[0],source_units:units,card_id:id,answer_anchor:a,rubric_anchor:r,explicit_recall:true,status:"covered",verified:true,source_excerpt:units.map(id=>load("actually_read").find(u=>u.unit_id===id)).filter(Boolean).map(u=>({unit_id:u.unit_id,text:u.text})),question_requirement:front,rubric_requirement:p[2],verification_note:p[4]||("人工逐点核对：源段/实见图支持“"+p[0]+"”；题干明确要求该项，完整答案"+a+"保留源文对象和条件，评分"+r+"以具体判定要求核查。")});
 });
 const source_units=[...all];cards.push({id,type:"Basic",chapter:ch,front,answer:answers,rubric:rubrics,detail:extra.detail||"",basis:extra.basis||"教材直接支持",source_units,knowledge_ids:ks,images:extra.images||[],tags:["学科::细胞生物学","章节::第"+String(ch).padStart(2,"0")+"章_"+load("titles")[ch].slice(3),"主题::"+topic,"任务::"+task,"卡片编号::"+id]});
 source_units.forEach(u=>{if(!handling[u])handling[u]={status:"mapped",cards:[],reason:"本单元的定义、限定条件和所述机制已逐点映射至题干、答案及评分。"};if(!handling[u].cards.includes(id))handling[u].cards.push(id);});
 return id;
}
globalThis.skip=function(u,reason,status="no_new_knowledge"){handling[u]={status,cards:[],reason};}
globalThis.read=function(us){const ar=load("actually_read");us.forEach(u=>{if(!ar.find(x=>x.unit_id===u.unit_id))ar.push({...u,reading_status:"actually_read"});});store("actually_read",ar);}
globalThis.save=function(){store("cards",cards);store("knowledge",knowledge);store("handling",handling);store("counters",ctr);}
